pub fn CallbackSig(comptime Type: type, comptime ResultType: type) type {
        return @TypeOf((struct {

pub fn f(_: *Type, status: ?Error, timeouts: i32, results: ResultType) void {
        _ = status;
        _ = timeouts;
        _ = results;
    }
}).f);
}

pub fn SockStateWrap(comptime Container: type) type {
        return struct {

pub fn onSockState(ctx: ?*anyopaque, socket: ares_socket_t, readable: c_int, writable: c_int) callconv(.c) void {
            const c_ptr = bun.cast(*Container, ctx.?);
            _ = Container.onDNSSocketState(c_ptr, socket, (readable != 0), (writable != 0));
    }
};
}

pub fn CallbackSigPtr(comptime Type: type, comptime Pointee: type) type {
        return @TypeOf((struct {

pub fn f(_: *Type, status: ?Error, timeouts: i32, results: ?*Pointee) void {
        _ = status;
        _ = timeouts;
        _ = results;
    }
}).f);
}

pub fn hostentCallback(comptime Type: type) type {
        return CallbackSigPtr(Type, struct_hostent);
}

pub fn hostentHostCallbackWrapper(comptime Type: type, comptime function: hostentCallback(Type)) ares_host_callback {
        return (&(struct {
        pub fn handle(ctx: ?*anyopaque, status: c_int, timeouts: c_int, hostent: OptStructHostentPtr) callconv(.c) void {
            const req = bun.cast(*Type, ctx.?);
            if (status != ARES_SUCCESS) {
                function(req, Error.get(status), timeouts, null);
                return;
            }
            function(req, null, timeouts, hostent);
        }
    }).handle);
}

pub fn hostentCallbackWrapper(comptime lookup_name: []const u8, comptime Type: type, comptime function: hostentCallback(Type)) ares_callback {
        return (&(struct {
        pub fn handle(ctx: ?*anyopaque, status: c_int, timeouts: c_int, buffer: [*c]u8, buffer_length: c_int) callconv(.c) void {
            const req = bun.cast(*Type, ctx.?);
            if (status != ARES_SUCCESS) {
                function(req, Error.get(status), timeouts, null);
                return;
            }

            var start: [*c]struct_hostent = undefined;
            if (comptime strings.eqlComptime(lookup_name, "cname")) {
                var addrttls: [256]struct_ares_addrttl = undefined;
                var naddrttls: i32 = 256;

                const result = ares_parse_a_reply(buffer, buffer_length, &start, &addrttls, &naddrttls);
                if (result != ARES_SUCCESS) {
                    function(req, Error.get(result), timeouts, null);
                    return;
                }
                function(req, null, timeouts, start);
            } else if (comptime strings.eqlComptime(lookup_name, "ns")) {
                const result = ares_parse_ns_reply(buffer, buffer_length, &start);
                if (result != ARES_SUCCESS) {
                    function(req, Error.get(result), timeouts, null);
                    return;
                }
                function(req, null, timeouts, start);
            } else if (comptime strings.eqlComptime(lookup_name, "ptr")) {
                const result = ares_parse_ptr_reply(buffer, buffer_length, null, 0, AF.INET, &start);
                if (result != ARES_SUCCESS) {
                    function(req, Error.get(result), timeouts, null);
                    return;
                }
                function(req, null, timeouts, start);
            } else {
                @compileError(std.fmt.comptimePrint("Unsupported struct_hostent record type: {s}", .{lookup_name}));
            }
        }
    }).handle);
}

