pub fn hostentWithTtlsCallbackWrapper(comptime lookup_name: []const u8, comptime Type: type, comptime function: hostentWithTtlsCallback(Type)) ares_callback {
        return (&(struct {
        pub fn handle(ctx: ?*anyopaque, status: c_int, timeouts: c_int, buffer: [*c]u8, buffer_length: c_int) callconv(.c) void {
            const req = bun.cast(*Type, ctx.?);
            if (status != ARES_SUCCESS) {
